function out(bool $ok,string $msg,array $data=[],int $status=200):never{http_response_code($status);echo json_encode(array_merge(['success'=>$ok,'message'=>$msg],$data),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
function input():array{$raw=file_get_contents('php://input');$j=json_decode((string)$raw,true);return is_array($j)?$j:$_POST;}
function cleanv(mixed $v,int $m):string{$s=trim((string)$v);return function_exists('mb_substr')?mb_substr($s,0,$m,'UTF-8'):substr($s,0,$m);}
function esc(string $s):string{return htmlspecialchars($s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function appUrl():string{$c=getenv('LOVEMI_APP_URL');if(is_string($c)&&trim($c)!=='')return rtrim(trim($c),'/');$https=(!empty($_SERVER['HTTPS'])&&strtolower((string)$_SERVER['HTTPS'])!=='off')||(int)($_SERVER['SERVER_PORT']??80)===443;$h=trim((string)($_SERVER['HTTP_HOST']??$_SERVER['SERVER_NAME']??'localhost'))?:'localhost';return ($https?'https':'http').'://'.$h.'/LOVEMI';}
