function col(PDO $pdo,string $t,string $c):bool{$s=$pdo->prepare('SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=:t AND COLUMN_NAME=:c');$s->execute([':t'=>$t,':c'=>$c]);return (int)$s->fetchColumn()>0;}function addc(PDO $pdo,string $t,string $c,string $d):void{if(!col($pdo,$t,$c))$pdo->exec("ALTER TABLE `$t` ADD COLUMN `$c` $d");}
$pdo->exec("CREATE TABLE IF NOT EXISTS support_tickets (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,user_id BIGINT UNSIGNED NULL,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL,category VARCHAR(40) NOT NULL DEFAULT 'other',subject VARCHAR(180) NOT NULL,message TEXT NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'open',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY idx_support_user_id(user_id),KEY idx_support_email(email),KEY idx_support_status(status),KEY idx_support_created_at(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
foreach([['source',"VARCHAR(20) NOT NULL DEFAULT 'help'"],['last_user_reply_at','DATETIME NULL'],['last_admin_reply_at','DATETIME NULL'],['last_message_at','DATETIME NULL'],['close_at','DATETIME NULL'],['solved_at','DATETIME NULL'],['closed_at','DATETIME NULL'],['reminder_24_sent','TINYINT(1) NOT NULL DEFAULT 0'],['reminder_12_sent','TINYINT(1) NOT NULL DEFAULT 0'],['reminder_1_sent','TINYINT(1) NOT NULL DEFAULT 0'],['admin_last_reminder_at','DATETIME NULL']] as $x)addc($pdo,'support_tickets',$x[0],$x[1]);
$pdo->exec("CREATE TABLE IF NOT EXISTS support_ticket_messages (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,ticket_id BIGINT UNSIGNED NOT NULL,sender_type VARCHAR(20) NOT NULL,sender_id BIGINT UNSIGNED NULL,sender_name VARCHAR(180) NOT NULL,sender_email VARCHAR(190) NOT NULL,body TEXT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY idx_stm_ticket(ticket_id),KEY idx_stm_created(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
$pdo->exec("CREATE TABLE IF NOT EXISTS support_ticket_access (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,ticket_id BIGINT UNSIGNED NOT NULL,access_type VARCHAR(20) NOT NULL DEFAULT 'guest',token_hash CHAR(64) NOT NULL,email_code_hash CHAR(64) NULL,email_code_expires_at DATETIME NULL,email_code_attempts INT UNSIGNED NOT NULL DEFAULT 0,email_code_sent_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY uq_sta_ticket(ticket_id),UNIQUE KEY uq_sta_token(token_hash)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
$userId=(int)($_SESSION['lovemi_user_id']??0);$currentUser=null;if($userId>0){$s=$pdo->prepare('SELECT id,username,full_names,email FROM users WHERE id=:id LIMIT 1');$s->execute([':id'=>$userId]);$currentUser=$s->fetch(PDO::FETCH_ASSOC)?:null;if(!$currentUser)$userId=0;}
$dup=$pdo->prepare('SELECT id FROM support_tickets WHERE email=:e AND subject=:s AND message=:m AND created_at>=DATE_SUB(CURRENT_TIMESTAMP,INTERVAL 5 MINUTE) ORDER BY id DESC LIMIT 1');$dup->execute([':e'=>$email,':s'=>$subject,':m'=>$message]);$duplicateId=$dup->fetchColumn();
if($duplicateId){$id=(int)$duplicateId;$a=$pdo->prepare('SELECT token_hash,access_type FROM support_ticket_access WHERE ticket_id=:id LIMIT 1');$a->execute([':id'=>$id]);$row=$a->fetch(PDO::FETCH_ASSOC);out(true,'This support request was already submitted recently.',['ticket_id'=>$id,'ticket_number'=>'LM-TKT-'.str_pad((string)$id,6,'0',STR_PAD_LEFT),'duplicate'=>true,'email_sent'=>true,'source'=>$source]);}
$token=bin2hex(random_bytes(48));$pdo->beginTransaction();try{$status='awaiting_admin';$st=$pdo->prepare("INSERT INTO support_tickets(user_id,name,email,category,subject,message,status,source,last_user_reply_at,last_message_at) VALUES(:uid,:name,:email,:category,:subject,:message,:status,:source,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)");$st->execute([':uid'=>$userId>0?$userId:null,':name'=>$name,':email'=>$email,':category'=>in_array($category,['account','login','premium','profile','connection','report','technical','contact','other'],true)?$category:'other',':subject'=>$subject,':message'=>$message,':status'=>$status,':source'=>$source]);$ticketId=(int)$pdo->lastInsertId();$m=$pdo->prepare("INSERT INTO support_ticket_messages(ticket_id,sender_type,sender_id,sender_name,sender_email,body) VALUES(:tid,'user',:sid,:name,:email,:body)");$m->execute([':tid'=>$ticketId,':sid'=>$userId>0?$userId:null,':name'=>$name,':email'=>$email,':body'=>$message]);$a=$pdo->prepare('INSERT INTO support_ticket_access(ticket_id,access_type,token_hash) VALUES(:tid,:type,:hash)');$a->execute([':tid'=>$ticketId,':type'=>$userId>0?'account':'guest',':hash'=>hash('sha256',$token)]);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('[LOVEMI SUPPORT INSERT] '.$e->getMessage());out(false,'The support ticket could not be saved.',['code'=>'TICKET_SAVE_FAILED'],500);}
$ticketNumber='LM-TKT-'.str_pad((string)$ticketId,6,'0',STR_PAD_LEFT);$feedbackUrl=appUrl().'/Support-Ticket-Feedback.html?token='.rawurlencode($token);$safeName=esc($name);$safeSubject=esc($subject);$safeMessage=nl2br(esc($message));$safeCategory=esc(ucfirst($category));
