$confirmationHtml='<div style="font-family:Arial,sans-serif;background:#f7f7fb;padding:26px"><div style="max-width:650px;margin:auto;background:#fff;border-radius:18px;padding:28px"><h2 style="color:#6d28d9">LOVEMI Support</h2><p>Hello '.$safeName.',</p><p>Your support message has been received.</p><div style="padding:16px;background:#faf9fc;border-radius:12px"><strong>Ticket:</strong> '.$ticketNumber.'<br><strong>Source:</strong> '.esc($source==='contact'?'Contact Center':'Help Center').'<br><strong>Subject:</strong> '.$safeSubject.'</div><p>Use the secure link below to view the conversation and reply to support:</p><p><a href="'.esc($feedbackUrl).'" style="display:inline-block;padding:13px 20px;border-radius:11px;background:#6d28d9;color:#fff;text-decoration:none;font-weight:800">Open Support Conversation</a></p><p style="font-size:12px;color:#777">Keep this link private. Account holders will also complete LOVEMI email and 2FA checks before seeing the ticket.</p></div></div>';
