out(true,'Your support ticket has been submitted.',['ticket_id'=>$ticketId,'ticket_number'=>$ticketNumber,'source'=>$source,'feedback_url'=>$feedbackUrl,'email_sent'=>$mailAdmin,'confirmation_sent'=>$confirm,'status'=>$mailAdmin?'received':'awaiting_admin'],201);
